function findCouncil(question) {
	const q = question.toLocaleLowerCase("en-NZ");
	const full = [...councils].sort((a, b) => b.name.length - a.name.length).find((c) => q.includes(c.name.toLocaleLowerCase("en-NZ")));
	if (full) return full;
	const short = councils.filter((c) => {
		const stem = c.name.toLocaleLowerCase("en-NZ").replace(/ (district|city|regional) council$/, "");
		return stem.length > 3 && q.includes(stem);
	});
	return short.length === 1 ? short[0] : void 0;
}
