var standards = "https://www.legislation.govt.nz/regulation/public/2022/0168/latest/whole.html";
var aesthetics = "https://www.taumataarowai.govt.nz/assets/Uploads/Rules-and-standards/Taumata-Arowai-Aesthetic-Values-for-Drinking-Water-2022.pdf";
