function contextualQuestion(q, previous) {
	if (!previous) return q;
	if (/ehinz|fluorid|nitrate|nitrite|chlorine|e[.\s-]*coli|boil water|do not drink|do not use|hinek[oō]rako|\breporting\b|\bmonitoring\b|submit|water notice|te mana o te wai|tikanga|source water|safety plan/i.test(q)) return q;
	return `${q} ${[
		[/ehinz/i, "EHiNZ drinking water surveillance"],
		[/fluorid/i, "fluoride in drinking water"],
		[/nitrate|nitrite/i, "nitrate in drinking water"],
		[/chlorine/i, "chlorine in drinking water"],
		[/e[.\s-]*coli/i, "E. coli in drinking water"],
		[/do not use/i, "Do Not Use Water notice"],
		[/do not drink/i, "Do Not Drink Water notice"],
		[/boil water/i, "Boil Water notice"],
		[/report/i, "drinking water reporting"],
		[/monitor/i, "drinking water monitoring"],
		[/te mana o te wai|tikanga/i, "Te Mana o te Wai"]
	].find(([pattern]) => pattern.test(previous.query))?.[1] || previous.q} ${previous.query.match(/\b\d{2,6}\s+people\b/i)?.[0] || ""}`.trim();
}
